import pdfplumber, re, json
import pandas as pd
from difflib import SequenceMatcher

vendors = pd.read_excel('/root/vendors.xlsx')
pos = pd.read_csv('/root/purchase_orders.csv')

# Build vendor lookup
import re
suffixes = {"ltd","limited","inc","incorporated","corp","corporation","co","company","llc"}

def normalize(name):
    name = name.lower()
    name = re.sub(r"[^a-z0-9\s]", " ", name)
    tokens = [t for t in name.split() if t]
    tokens = [t for t in tokens if t not in suffixes]
    return " ".join(tokens)

vendor_norm = {normalize(n): (vid, n, iban) for vid, n, iban in vendors[['id','name','iban']].itertuples(index=False, name=None)}
# If duplicates exist, keep first; shouldn't happen.

vendor_norm_list = list(vendor_norm.items())


def match_vendor(name):
    n = normalize(name)
    if n in vendor_norm:
        return vendor_norm[n], 1.0
    # fuzzy
    best = (0.0, None)
    for norm_name, data in vendor_norm_list:
        ratio = SequenceMatcher(None, n, norm_name).ratio()
        if ratio > best[0]:
            best = (ratio, data)
    if best[0] >= 0.85:
        return best[1], best[0]
    return None, best[0]

po_by_number = {row.po_number: row for row in pos.itertuples(index=False)}

pattern = re.compile(r"From: (?P<vendor>.+?)\s*\|\s*Total \$(?P<amount>[0-9,.]+)\s*\|\s*Payment IBAN: (?P<iban>[^|]+)\s*\|\s*PO Number: (?P<po>.+)")

fraud = []

with pdfplumber.open('/root/invoices.pdf') as pdf:
    for idx, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''
        m = pattern.search(text)
        if not m:
            # skip or handle? we'll record as unknown vendor with null? but instructions not.
            continue
        vendor_name = m.group('vendor').strip()
        amount = float(m.group('amount').replace(',', ''))
        iban = m.group('iban').strip()
        po_number = m.group('po').strip()

        # Determine reason
        vendor_data, ratio = match_vendor(vendor_name)
        reason = None
        matched_vendor_id = None
        matched_vendor_iban = None
        if not vendor_data:
            reason = 'Unknown Vendor'
        else:
            matched_vendor_id, matched_vendor_name, matched_vendor_iban = vendor_data
            if iban != matched_vendor_iban:
                reason = 'IBAN Mismatch'
            else:
                po_row = po_by_number.get(po_number)
                if po_row is None:
                    reason = 'Invalid PO'
                else:
                    # amount mismatch threshold > 0.01
                    if abs(float(po_row.amount) - amount) > 0.01:
                        reason = 'Amount Mismatch'
                    else:
                        if po_row.vendor_id != matched_vendor_id:
                            reason = 'Vendor Mismatch'

        if reason:
            fraud.append({
                'invoice_page_number': idx,
                'vendor_name': vendor_name,
                'invoice_amount': round(amount, 2),
                'iban': iban,
                'po_number': None if (po_number.strip()=='' ) else po_number,
                'reason': reason
            })

print('fraud count', len(fraud))
# show first few
print(fraud[:5])

# Save
with open('/root/fraud_report.json', 'w') as f:
    json.dump(fraud, f, indent=2)

